  function createEditor(root, { format, readOnly = false, value = "", onInput } = {}) {
    root.classList.add("editor");
    const pre = document.createElement("pre");
    pre.className = "editor-hl";
    pre.setAttribute("aria-hidden", "true");
    const code = document.createElement("code");
    pre.appendChild(code);
    const ta = document.createElement("textarea");
    ta.className = "editor-input";
    ta.spellcheck = false;
    ta.autocapitalize = "off";
    ta.autocomplete = "off";
    ta.setAttribute("autocorrect", "off");
    ta.wrap = "off";
    ta.readOnly = readOnly;
    ta.value = value;
    root.append(pre, ta);
    let fmt = format;
    function render() {
      code.innerHTML = highlight(fmt, ta.value) + "\n";
    }
    function syncScroll() {
      pre.scrollTop = ta.scrollTop;
      pre.scrollLeft = ta.scrollLeft;
    }
    ta.addEventListener("input", () => {
      render();
      syncScroll();
      onInput?.(ta.value);
    });
    ta.addEventListener("scroll", syncScroll, { passive: true });
    ta.addEventListener("keydown", (e2) => {
      if (e2.key === "Tab" && !readOnly) {
        e2.preventDefault();
        const s2 = ta.selectionStart, en = ta.selectionEnd;
        ta.value = ta.value.slice(0, s2) + "  " + ta.value.slice(en);
        ta.selectionStart = ta.selectionEnd = s2 + 2;
        ta.dispatchEvent(new Event("input"));
      }
    });
    render();
    return {
      el: root,
      get value() {
        return ta.value;
      },
      setValue(v2) {
        ta.value = v2;
        render();
        syncScroll();
      },
      setFormat(f2) {
        fmt = f2;
        render();
      },
      focus() {
        ta.focus();
      },
      textarea: ta
    };
  }

